kernel-trick.pseudocode:
def kernel(x, z, kind='rbf', gamma=0.5, deg=3):
    if kind == 'linear':
        return dot(x, z)
    if kind == 'poly':  # (x·z + 1)^d
        return (dot(x, z) + 1) ** deg
    if kind == 'rbf':  # exp(-γ‖x-z‖²)
        diff = [a - b for a, b in zip(x, z)]
        return exp(-gamma * dot(diff, diff))

def decision(x, sv, alpha, y, b, kind='rbf'):
    # φ 계산 없이 커널 내적만으로 판별
    s = b
    for i in range(len(sv)):
        s += alpha[i] * y[i] * kernel(sv[i], x, kind)
    return 1 if s >= 0 else -1

key-stretching.pseudocode:
def xor_bytes(a, b):
    return bytes(x ^ y for x, y in zip(a, b))

def pbkdf2_block(prf, pw, salt, c, i):
    u = prf(pw, salt + i.to_bytes(4, 'big'))  # U1
    t = u
    for _ in range(c - 1):  # c회 반복 → 공격 비용 c배
        u = prf(pw, u)  # Uj = PRF(pw, Uj-1)
        t = xor_bytes(t, u)  # 모든 중간값 XOR 누적
    return t

def pbkdf2(prf, pw, salt, c, dk_len, h_len):
    n_blocks = -(-dk_len // h_len)  # 올림 나눗셈
    dk = b''
    for i in range(1, n_blocks + 1):
        dk += pbkdf2_block(prf, pw, salt, c, i)
    return dk[:dk_len]

keyframe-animation.pseudocode:
def interpolate(key_a, key_b, t):
    # key = (time, value), t: 현재 시각
    span = key_b[0] - key_a[0]
    if span == 0:
        return key_a[1]
    r = (t - key_a[0]) / span  # 0~1 보간 비율
    r = ease_in_out(r)  # F-Curve로 가감속
    return key_a[1] + (key_b[1] - key_a[1]) * r

def ease_in_out(r):  # 스무스스텝(감속·가속)
    return r * r * (3 - 2 * r)
